# AUTO-GENERATED by _add_daily_fortune.py
"""
일운(日運) — 오늘의 기운.

입력: target_date, 사용자 일간, 나에게 힘이 되는 기운 정보
출력: 해당 날짜의 오늘의 기운, 십성, 스코어, 등급

일운은 이번 달의 흐름/인생의 큰 흐름보다 가볍게 1.0x/1.5x 가중치 (하루는 영향 작음).
"""
from datetime import date, timedelta

from app.engine.pillars import get_day_pillar
from app.engine.elements import (
    get_ten_god, TEN_GOD_CODES, STEM_TO_ELEMENT, BRANCH_MAIN_STEM,
)
from app.engine.daewoon_score import _element_score, _grade
from app.semantic.tags import DAEWOON_GRADES


_DAY_STEM_WEIGHT = 1.0
_DAY_BRANCH_WEIGHT = 1.5


def calculate_daily_fortune(
    target_date: date,
    day_stem: str,
    yongsin_info: dict,
) -> dict:
    """하루치 일운."""
    day_pillar = get_day_pillar(target_date, jasi_boundary=0)
    stem, branch = day_pillar[0], day_pillar[1]

    ten_god_kr = get_ten_god(day_stem, stem)
    ten_god_code = TEN_GOD_CODES.get(ten_god_kr, ten_god_kr)

    stem_elem = STEM_TO_ELEMENT.get(stem, "")
    branch_main = BRANCH_MAIN_STEM.get(branch, "")
    branch_elem = STEM_TO_ELEMENT.get(branch_main, "")

    score = (
        _element_score(stem_elem, yongsin_info) * _DAY_STEM_WEIGHT
        + _element_score(branch_elem, yongsin_info) * _DAY_BRANCH_WEIGHT
    )
    score = round(max(-2.5, min(2.5, score)), 2)
    grade = DAEWOON_GRADES.get(_grade(score)["ko"], "NEUTRAL")

    return {
        "date": target_date.isoformat(),
        "day_pillar": day_pillar,
        "stem": stem,
        "branch": branch,
        "stem_element": stem_elem,
        "branch_element": branch_elem,
        "ten_god": ten_god_code,
        "score": score,
        "grade": grade,
    }


def calculate_daily_range(
    start_date: date,
    days: int,
    day_stem: str,
    yongsin_info: dict,
) -> list:
    """start_date부터 days일치."""
    return [
        calculate_daily_fortune(start_date + timedelta(days=i), day_stem, yongsin_info)
        for i in range(days)
    ]
